(()=>{
  'use strict';
  const host=document.getElementById('aqua-spirit');if(!host)return;
  const canvas=host.querySelector('.spirit-live-canvas'),close=host.querySelector('.spirit-close');
  let ctx=null;try{ctx=canvas.getContext('2d',{alpha:true});}catch(_){return;}if(!ctx)return;
  const hero=document.querySelector('.hero');
  const reduced=matchMedia('(prefers-reduced-motion: reduce)'),fine=matchMedia('(any-hover:hover) and (any-pointer:fine)');
  const textureSource='data:image/png;base64,';
  const image=new Image();
  const mirror=document.createElement('canvas'),mirrorCtx=mirror.getContext('2d');
  const fallback=document.createElement('canvas');fallback.width=fallback.height=384;
  const fallbackCtx=fallback.getContext('2d');
  const state={lookX:0,lookY:0,eyeX:0,eyeY:0,near:0,energy:0};
  const velocity={...state},goal={...state};
  let renderer=null,loaded=false,closed=false,visible=true,focused=true;
  let width=124,height=168,dpr=1,faceX=0,faceY=0;
  let raf=0,lastFrame=0,clock=0,lastInput=-9999,lastPointer=null;
  let nextBlink=5.5+Math.random()*5,blinkStart=-9999;
  const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
  const canAnimate=()=>loaded&&!closed&&visible&&focused&&!document.hidden&&!reduced.matches;

  // One neutral texture is attached to a deformable mesh. Joint weights move
  // the head, arms, gills and tail continuously; there are no pose swaps.
  function makeRenderer(){
    const surface=document.createElement('canvas');surface.width=surface.height=384;
    let gl=null;
    try{
      gl=surface.getContext('webgl',{alpha:true,antialias:true,depth:false,stencil:false,premultipliedAlpha:false,preserveDrawingBuffer:true,powerPreference:'low-power'});
      if(!gl)return null;
      const vertex=`
        precision highp float;
        attribute vec2 a_position;
        uniform float u_time,u_near,u_energy;
        uniform vec2 u_look;
        varying vec2 v_rest;
        mat2 rotation(float a){float c=cos(a),s=sin(a);return mat2(c,s,-s,c);}
        float region(vec2 p,vec2 c,vec2 r){vec2 d=(p-c)/r;return exp(-dot(d,d)*1.8);}
        void main(){
          vec2 rest=a_position,p=rest;v_rest=rest;
          float t=u_time;
          float body=smoothstep(0.54,0.85,rest.y);
          float breath=sin(t*1.35)*0.009;
          p.x+=(rest.x-0.54)*breath*body;
          p.y-=body*breath*0.22;
          float tail=region(rest,vec2(0.34,0.81),vec2(0.23,0.12));
          p.y+=tail*sin(t*1.85+rest.x*7.0)*(0.012+u_near*0.009);
          p.x+=tail*cos(t*1.1+rest.y*6.0)*0.006;
          vec2 shoulderL=vec2(0.46,0.655),shoulderR=vec2(0.61,0.65);
          float armL=region(rest,vec2(0.476,0.713),vec2(0.077,0.104));
          float armR=region(rest,vec2(0.636,0.714),vec2(0.077,0.104));
          float angleL=sin(t*1.65+0.7)*0.075+u_near*0.11;
          float angleR=-u_near*(0.48+sin(t*3.6)*0.11)-u_energy*0.18;
          p+=(shoulderL+rotation(angleL)*(rest-shoulderL)-rest)*armL;
          p+=(shoulderR+rotation(angleR)*(rest-shoulderR)-rest)*armR;
          float head=1.0-smoothstep(0.57,0.69,rest.y);
          vec2 headCenter=vec2(0.55,0.38);
          vec2 turned=headCenter+rotation(u_look.x*0.035+sin(t*0.53)*0.004)*(rest-headCenter);
          p+=(turned-rest+vec2(u_look.x*0.014,u_look.y*0.010))*head;
          float gillL=region(rest,vec2(0.19,0.31),vec2(0.12,0.22));
          float gillR=region(rest,vec2(0.83,0.24),vec2(0.12,0.22));
          p.y+=sin(t*1.7+rest.y*8.0)*0.006*(gillL-gillR);
          p.x+=cos(t*1.1+rest.y*6.0)*0.004*(gillL-gillR);
          vec2 center=vec2(0.54,0.72);
          float sway=u_look.x*0.018+sin(t*0.72)*0.009+sin(t*6.5)*u_energy*0.017;
          p=center+rotation(sway)*(p-center);
          p.y-=sin(t*0.91)*0.010+u_near*0.011;
          gl_Position=vec4(p.x*2.0-1.0,1.0-p.y*2.0,0.0,1.0);
        }`;
      const fragment=`
        precision highp float;
        uniform sampler2D u_texture;
        uniform vec2 u_eye;
        uniform float u_blink;
        varying vec2 v_rest;
        float eye(vec2 center){
          vec2 radius=vec2(0.0225,max(0.0015,0.0225*u_blink));
          float d=length((v_rest-center-u_eye)/radius);
          return 1.0-smoothstep(0.83,1.12,d);
        }
        void main(){
          vec4 color=texture2D(u_texture,v_rest*0.5);
          if(color.a<0.015)discard;
          float eyes=max(eye(vec2(0.454,0.466)),eye(vec2(0.640,0.439)));
          color.rgb=mix(color.rgb,vec3(0.065,0.185,0.285),eyes*0.96);
          gl_FragColor=color;
        }`;
      function compile(type,source){
        const shader=gl.createShader(type);if(!shader)throw new Error('Shader unavailable');
        gl.shaderSource(shader,source);gl.compileShader(shader);
        if(!gl.getShaderParameter(shader,gl.COMPILE_STATUS)){gl.deleteShader(shader);throw new Error('Shader compilation unavailable');}
        return shader;
      }
      const vs=compile(gl.VERTEX_SHADER,vertex),fs=compile(gl.FRAGMENT_SHADER,fragment);
      const program=gl.createProgram();gl.attachShader(program,vs);gl.attachShader(program,fs);gl.linkProgram(program);
      gl.deleteShader(vs);gl.deleteShader(fs);
      if(!gl.getProgramParameter(program,gl.LINK_STATUS))return null;
      gl.useProgram(program);
      const divisions=24,vertices=[],indices=[];
      for(let y=0;y<=divisions;y++)for(let x=0;x<=divisions;x++)vertices.push(x/divisions,y/divisions);
      for(let y=0;y<divisions;y++)for(let x=0;x<divisions;x++){
        const a=y*(divisions+1)+x,b=a+1,c=a+divisions+1,d=c+1;
        indices.push(a,c,b,b,c,d);
      }
      const vb=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,vb);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array(vertices),gl.STATIC_DRAW);
      const position=gl.getAttribLocation(program,'a_position');gl.enableVertexAttribArray(position);gl.vertexAttribPointer(position,2,gl.FLOAT,false,0,0);
      const ib=gl.createBuffer();gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER,ib);gl.bufferData(gl.ELEMENT_ARRAY_BUFFER,new Uint16Array(indices),gl.STATIC_DRAW);
      const texture=gl.createTexture();gl.activeTexture(gl.TEXTURE0);gl.bindTexture(gl.TEXTURE_2D,texture);
      gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL,false);gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL,false);
      gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MIN_FILTER,gl.LINEAR);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MAG_FILTER,gl.LINEAR);
      gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_S,gl.CLAMP_TO_EDGE);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_T,gl.CLAMP_TO_EDGE);
      gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,gl.RGBA,gl.UNSIGNED_BYTE,image);
      gl.uniform1i(gl.getUniformLocation(program,'u_texture'),0);
      const uniforms={};for(const name of ['time','near','energy','look','eye','blink'])uniforms[name]=gl.getUniformLocation(program,'u_'+name);
      gl.viewport(0,0,384,384);gl.clearColor(0,0,0,0);
      surface.addEventListener('webglcontextlost',event=>{event.preventDefault();renderer=null;});
      return{
        canvas:surface,
        draw(t,blink){
          if(gl.isContextLost())return false;
          gl.useProgram(program);gl.clear(gl.COLOR_BUFFER_BIT);
          gl.uniform1f(uniforms.time,t);gl.uniform1f(uniforms.near,state.near);gl.uniform1f(uniforms.energy,state.energy);
          gl.uniform2f(uniforms.look,state.lookX,state.lookY);gl.uniform2f(uniforms.eye,state.eyeX,state.eyeY);gl.uniform1f(uniforms.blink,blink);
          gl.drawElements(gl.TRIANGLES,indices.length,gl.UNSIGNED_SHORT,0);return true;
        }
      };
    }catch(_){return null;}
  }

  function drawFallback(t,blink){
    if(!fallbackCtx)return null;
    const c=fallbackCtx,s=384; c.clearRect(0,0,s,s);c.save();
    c.translate(s*.54,s*.72);c.rotate(state.lookX*.03+Math.sin(t*.72)*.009);
    c.scale(1+Math.sin(t*1.35)*.003,1+Math.sin(t*1.35)*.002);c.translate(-s*.54,-s*.72-Math.sin(t*.91)*2.5-state.near*3);
    c.drawImage(image,0,0,image.width/2,image.height/2,0,0,s,s);
    c.fillStyle='#14334c';
    for(const [x,y] of [[.454,.466],[.640,.439]]){
      c.beginPath();c.ellipse((x+state.eyeX)*s,(y+state.eyeY)*s,s*.0225,s*Math.max(.0015,.0225*blink),0,0,Math.PI*2);c.fill();
    }
    c.restore();return fallback;
  }

  function blinkValue(){
    if(reduced.matches)return 1;
    if(clock>=nextBlink){blinkStart=clock;nextBlink=clock+6+Math.random()*6;}
    const progress=(clock-blinkStart)/.24;
    return progress>=0&&progress<=1?1-.92*Math.sin(progress*Math.PI):1;
  }
  function render(){
    if(!loaded)return;
    const blink=blinkValue();let body=null;
    if(renderer){try{if(renderer.draw(clock,blink))body=renderer.canvas;else renderer=null;}catch(_){renderer=null;}}
    if(!body)body=drawFallback(clock,blink);if(!body)return;
    ctx.clearRect(0,0,width,height);
    const floor=width*.92,softness=width/124;
    // A faint contact pool anchors the spirit without a visible rectangular floor.
    ctx.save();ctx.translate(width*.54,floor+2);ctx.scale(1,.13);
    const pool=ctx.createRadialGradient(0,0,0,0,0,width*.43);
    pool.addColorStop(0,'rgba(70,157,183,.09)');pool.addColorStop(1,'rgba(70,157,183,0)');
    ctx.fillStyle=pool;ctx.fillRect(-width*.46,-width*.46,width*.92,width*.92);ctx.restore();
    if(mirrorCtx){
      mirrorCtx.clearRect(0,0,width,height);mirrorCtx.save();
      mirrorCtx.translate(0,floor*2+2);mirrorCtx.scale(1,-1);mirrorCtx.globalAlpha=.23-state.near*.025;
      mirrorCtx.filter=`blur(${3.2*softness}px) saturate(90%)`;mirrorCtx.drawImage(body,0,0,width,width);mirrorCtx.restore();
      mirrorCtx.globalCompositeOperation='destination-in';
      const fade=mirrorCtx.createLinearGradient(0,floor,0,floor+width*.38);
      fade.addColorStop(0,'rgba(255,255,255,.75)');fade.addColorStop(.24,'rgba(255,255,255,.36)');fade.addColorStop(.7,'rgba(255,255,255,.05)');fade.addColorStop(1,'rgba(255,255,255,0)');
      mirrorCtx.fillStyle=fade;mirrorCtx.fillRect(0,0,width,height);mirrorCtx.globalCompositeOperation='source-over';
      mirrorCtx.clearRect(0,0,width,floor);
      ctx.drawImage(mirror,0,0,mirror.width,mirror.height,0,0,width,height);
    }
    // Keep every visible layer softly focused, including the eyes. A broad,
    // faint halo and a middle diffusion layer let the silhouette dissolve
    // into the page rather than leave a sharp sticker-like outline.
    ctx.save();ctx.globalAlpha=.17;ctx.filter=`blur(${6.8*softness}px) saturate(118%)`;ctx.drawImage(body,0,0,width,width);ctx.restore();
    ctx.save();ctx.globalAlpha=.30;ctx.filter=`blur(${3.1*softness}px) saturate(112%)`;ctx.drawImage(body,0,0,width,width);ctx.restore();
    ctx.save();ctx.globalAlpha=.72;ctx.filter=`blur(${(1.65+state.energy*.35)*softness}px) saturate(112%) contrast(96%)`;ctx.drawImage(body,0,0,width,width);ctx.restore();
  }

  function measure(){
    const rect=host.getBoundingClientRect();width=rect.width||124;height=rect.height||168;
    faceX=rect.left+width*.553;faceY=rect.top+width*.45;
    dpr=Math.min(devicePixelRatio||1,1.5);
    canvas.width=Math.round(width*dpr);canvas.height=Math.round(height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);
    mirror.width=canvas.width;mirror.height=canvas.height;if(mirrorCtx)mirrorCtx.setTransform(dpr,0,0,dpr,0,0);
    render();
  }
  function tick(now){
    raf=0;if(!canAnimate())return;
    const recent=now-lastInput<600;
    if(!lastFrame||now-lastFrame>=(recent?15:32)){
      const dt=Math.min(lastFrame?(now-lastFrame)/1000:1/60,.06);lastFrame=now;clock+=dt;
      if(now-lastInput>1600){goal.lookX=goal.lookY=goal.eyeX=goal.eyeY=goal.near=0;}
      goal.energy*=Math.exp(-dt*4.6);
      const steps=Math.max(1,Math.ceil(dt/.012)),step=dt/steps;
      for(let i=0;i<steps;i++)for(const key of Object.keys(state)){
        const eyes=key==='eyeX'||key==='eyeY',k=eyes?160:key==='near'?55:85;
        const damping=eyes?26:key==='near'?16:20;
        velocity[key]+=((goal[key]-state[key])*k-velocity[key]*damping)*step;state[key]+=velocity[key]*step;
      }
      state.near=clamp(state.near,0,1);state.energy=clamp(state.energy,0,1);render();
    }
    raf=requestAnimationFrame(tick);
  }
  function sync(){
    cancelAnimationFrame(raf);raf=0;lastFrame=0;lastPointer=null;
    if(canAnimate())raf=requestAnimationFrame(tick);
    else{for(const key of Object.keys(state)){state[key]=goal[key]=velocity[key]=0;}render();}
  }
  addEventListener('pointermove',event=>{
    if(event.pointerType==='touch'||!fine.matches||!canAnimate())return;
    const now=performance.now(),dx=event.clientX-faceX,dy=event.clientY-faceY,distance=Math.hypot(dx,dy);
    const angle=Math.atan2(dy,dx),strength=Math.min(1,distance/320);
    goal.eyeX=Math.cos(angle)*strength*.017;goal.eyeY=Math.sin(angle)*strength*.012;
    goal.lookX=clamp(dx/Math.max(300,innerWidth*.6),-1,1);goal.lookY=clamp(dy/Math.max(260,innerHeight*.6),-1,1);
    goal.near=Math.exp(-(distance*distance)/(225*225));
    if(lastPointer&&now-lastPointer.time<160){
      const speed=Math.hypot(event.clientX-lastPointer.x,event.clientY-lastPointer.y)/Math.max(.012,(now-lastPointer.time)/1000);
      goal.energy=Math.max(goal.energy,Math.min(1,speed/1800)*Math.exp(-distance/700));
    }
    lastPointer={x:event.clientX,y:event.clientY,time:now};lastInput=now;
  },{passive:true});
  addEventListener('pointerdown',event=>{
    if(event.pointerType!=='touch'||!canAnimate())return;
    const distance=Math.hypot(event.clientX-faceX,event.clientY-faceY);
    if(distance<160){goal.near=1;goal.energy=.2;lastInput=performance.now();}
  },{passive:true});
  document.addEventListener('mouseleave',()=>{for(const key of Object.keys(goal))goal[key]=0;lastPointer=null;});
  addEventListener('blur',()=>{focused=false;sync();});addEventListener('focus',()=>{focused=true;sync();});
  addEventListener('resize',measure,{passive:true});document.addEventListener('visibilitychange',sync);
  reduced.addEventListener?.('change',sync);fine.addEventListener?.('change',sync);
  close.addEventListener('click',()=>{closed=true;host.dataset.closed='true';sync();});
  if(hero&&'IntersectionObserver' in window){
    new IntersectionObserver(entries=>{visible=entries[0].isIntersecting&&entries[0].intersectionRatio>.12;host.dataset.visible=String(visible);sync();},{threshold:[0,.12,.2]}).observe(hero);
  }
  image.onload=()=>{loaded=true;renderer=makeRenderer();host.dataset.renderer=renderer?'mesh':'canvas';measure();sync();};
  image.onerror=()=>{host.dataset.closed='true';};
  image.src=textureSource;measure();
})();
